var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original regex allowed "100" as a valid input, but the new one does not.
    // This test checks that "100kb" is parsed correctly, but also that "100" is parsed as 100 bytes.
    assert.strictEqual(bytes.parse('100'), 100);
    assert.strictEqual(bytes.parse('100kb'), 102400);
  });
});

