var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Original: 1 year = 365.25 days, so 1y should be ~31,557,600,000 ms
    // Patched: y = d / 365.25, so 1y is ~236,550 ms (about 4 minutes)
    assert.strictEqual(ms('1y'), 31557600000);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code correctly returns '1 year' for 1 year
    // The patched code returns '1 ms' because the 'y' case was removed
    // and the default case is reached for 'y' (which is invalid)
    assert.strictEqual(ms(365.25 * 24 * 60 * 60 * 1000, { long: true }), '1 year');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Original: 1 year should be 365.25 days, so 365.25 * 24 * 60 * 60 * 1000 ms
    // Patched: 1 year is now n / y, so 1 / (365.25 * 24 * 60 * 60 * 1000) ms
    // This is a very small number, not 1 year
    assert.strictEqual(ms('1y', { long: true }), '365.25 days');
  });
});
